INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ar', 'يركز هذا المشروع على احتياجات الترميم الأساسية للبازيليكا، بما في ذلك الإصلاحات الإنشائية، وتنظيف الواجهة، والحفاظ على العناصر المعمارية الأصلية. سيضمن هذا العمل بقاء المبنى آمنًا وسهل الوصول إليه للأجيال القادمة.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
