INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'es', 'Restauración', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'es', 'Este proyecto se centra en las necesidades críticas de restauración de la basílica, incluidas las reparaciones estructurales, la limpieza de la fachada y la conservación de los elementos arquitectónicos originales. Este trabajo garantizará que el edificio siga siendo seguro y accesible para las generaciones futuras.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'es', 'Restauración de la nave principal y la fachada de la Basílica de la Anunciación.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'es', 'Restauración de la basílica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'es', 'Documentación', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'es', 'Una iniciativa integral para fotografiar, escanear y documentar sitios, objetos y manuscritos del patrimonio cristiano en Israel y las regiones circundantes. Este archivo digital preservará registros históricos de valor incalculable para investigadores y para las generaciones futuras.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'es', 'Documentación digital de los sitios del patrimonio cristiano en toda Tierra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'es', 'Documentación del patrimonio de Tierra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'fr', 'La Basilique de l''Annonciation est une église catholique de Nazareth, en Israël. C''est l''une des plus grandes églises du Moyen-Orient, et elle marque le lieu traditionnel où l''archange Gabriel annonça à Marie qu''elle enfanterait Jésus.', 'La basilique actuelle a été construite en 1969, selon les plans de l''architecte italien Giovanni Muzio. Elle s''élève au-dessus des vestiges d''églises byzantines et croisées antérieures. Le site est un lieu de pèlerinage chrétien depuis l''Antiquité.', 'L''église sert la communauté catholique locale de Nazareth et accueille des pèlerins du monde entier. Des messes régulières y sont célébrées en plusieurs langues.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'fr', 'La Basilique de la Nativité, à Bethléem, s''élève au-dessus de la grotte que la tradition chrétienne honore depuis le IIe siècle comme le lieu de naissance de Jésus. C''est l''une des plus anciennes églises en usage continu au monde et un site du patrimoine mondial de l''UNESCO.', 'La première basilique fut commandée par l''empereur Constantin et sa mère Hélène vers 327 apr. J.-C. Après avoir été endommagée au VIe siècle, l''empereur Justinien la reconstruisit à plus grande échelle, et une grande partie de l''église actuelle date de cette reconstruction. Des mosaïques et des colonnes peintes de l''époque des Croisades subsistent encore à l''intérieur.', 'L''église est partagée par les communautés grecque orthodoxe, catholique romaine (franciscaine) et apostolique arménienne selon l''accord historique du Statu quo. Les familles chrétiennes locales de Bethléem y prient aux côtés de pèlerins venus du monde entier, en particulier à Noël.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'fr', 'L''Église du Saint-Sépulcre, dans la vieille ville de Jérusalem, renferme les deux lieux les plus sacrés du christianisme : le Golgotha, où Jésus fut crucifié, et le tombeau où, selon la tradition, il fut enseveli puis ressuscita.', 'L''empereur Constantin fit construire la première église sur ce site au IVe siècle ; elle fut consacrée en 335 apr. J.-C. Détruite en 1009, elle fut reconstruite au XIe siècle, et les croisés lui donnèrent l''essentiel de sa forme actuelle au XIIe siècle. L''édicule surmontant le tombeau a été restauré entre 2016 et 2017.', 'L''entretien de l''église est partagé par les Églises grecque orthodoxe, catholique romaine (franciscaine) et apostolique arménienne, tandis que les communautés copte, éthiopienne et syriaque orthodoxe possèdent également leurs propres chapelles, conformément au Statu quo de 1852. Ses portes sont ouvertes chaque matin par des familles musulmanes qui en gardent les clés depuis des siècles.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
