INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'fr', 'Ce projet porte sur les besoins essentiels de restauration de la basilique, notamment les réparations structurelles, le nettoyage de la façade et la préservation des éléments architecturaux d''origine. Ces travaux garantiront que le bâtiment reste sûr et accessible pour les générations futures.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'fr', 'Restauration de la nef principale et de la façade de la Basilique de l''Annonciation.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
