INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'he', 'יוזמה מקיפה לצילום, סריקה ותיעוד של אתרי מורשת נוצרית, ממצאים וכתבי יד ברחבי ישראל והאזורים הסובבים. הארכיון הדיגיטלי הזה ישמר תיעוד היסטורי יקר ערך עבור חוקרים ולדורות הבאים.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
