INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'it', 'La Basilica dell''Annunciazione è una chiesa cattolica situata a Nazareth, in Israele. È una delle chiese più grandi del Medio Oriente e segna il luogo tradizionale in cui l''arcangelo Gabriele annunciò a Maria che avrebbe concepito Gesù.', 'L''attuale basilica fu costruita nel 1969, su progetto dell''architetto italiano Giovanni Muzio. Sorge sulle rovine di precedenti chiese bizantine e crociate. Il sito è meta di pellegrinaggio cristiano fin dall''antichità.', 'La chiesa serve la comunità cattolica locale di Nazareth e accoglie pellegrini da tutto il mondo. Vi si celebrano regolarmente sante messe in diverse lingue.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'it', 'La Basilica della Natività, a Betlemme, sorge sopra la grotta che la tradizione cristiana venera fin dal II secolo come luogo di nascita di Gesù. È una delle chiese più antiche al mondo ancora in uso ininterrotto ed è patrimonio dell''umanità UNESCO.', 'La prima basilica fu commissionata dall''imperatore Costantino e da sua madre Elena intorno al 327 d.C. Dopo essere stata danneggiata nel VI secolo, l''imperatore Giustiniano la ricostruì su scala maggiore, e gran parte della chiesa attuale risale a quella ricostruzione. All''interno si conservano ancora mosaici e colonne dipinte dell''epoca crociata.', 'La chiesa è condivisa dalle comunità greco-ortodossa, cattolica romana (francescana) e apostolica armena secondo lo storico accordo dello Status quo. Le famiglie cristiane locali di Betlemme vi pregano insieme ai pellegrini provenienti da tutto il mondo, specialmente a Natale.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'it', 'La Basilica del Santo Sepolcro, nella Città Vecchia di Gerusalemme, custodisce i due luoghi più sacri della cristianità: il Golgota, dove Gesù fu crocifisso, e il sepolcro dove, secondo la tradizione, fu sepolto e risorse.', 'L''imperatore Costantino fece costruire qui la prima chiesa nel IV secolo; fu consacrata nel 335 d.C. Fu distrutta nel 1009 e ricostruita nell''XI secolo, e i crociati le diedero gran parte della sua forma attuale nel XII secolo. L''Edicola sopra il sepolcro è stata restaurata tra il 2016 e il 2017.', 'La cura della chiesa è condivisa dalle chiese greco-ortodossa, cattolica romana (francescana) e apostolica armena, mentre le comunità copta, etiope e siro-ortodossa mantengono anch''esse proprie cappelle, in base allo Status quo del 1852. Le sue porte vengono aperte ogni mattina da famiglie musulmane che ne custodiscono le chiavi da secoli.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
