INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'it', 'Restauro', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'it', 'Questo progetto si concentra sulle esigenze fondamentali di restauro della basilica, tra cui riparazioni strutturali, pulizia della facciata e conservazione degli elementi architettonici originali. I lavori garantiranno che l''edificio rimanga sicuro e accessibile per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'it', 'Restauro della navata principale e della facciata della Basilica dell''Annunciazione.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'it', 'Restauro della basilica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'it', 'Documentazione', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'it', 'Un''iniziativa completa per fotografare, scansionare e documentare siti, manufatti e manoscritti del patrimonio cristiano in Israele e nelle regioni circostanti. Questo archivio digitale preserverà documenti storici inestimabili per i ricercatori e per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'it', 'Documentazione digitale dei siti del patrimonio cristiano in tutta la Terra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'it', 'Documentazione del patrimonio di Terra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'pt', 'A Basílica da Anunciação é uma igreja católica em Nazaré, Israel. É uma das maiores igrejas do Oriente Médio e marca o local tradicional onde o Arcanjo Gabriel anunciou a Maria que ela geraria Jesus.', 'A basílica atual foi construída em 1969, com projeto do arquiteto italiano Giovanni Muzio. Ela se ergue sobre as ruínas de igrejas bizantinas e cruzadas anteriores. O local é um destino de peregrinação cristã desde a Antiguidade.', 'A igreja atende a comunidade católica local de Nazaré e recebe peregrinos de todo o mundo. Missas regulares são celebradas em vários idiomas.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'pt', 'A Basílica da Natividade, em Belém, ergue-se sobre a gruta que a tradição cristã venera desde o século II como o local de nascimento de Jesus. É uma das igrejas em uso contínuo mais antigas do mundo e Patrimônio Mundial da UNESCO.', 'A primeira basílica foi encomendada pelo imperador Constantino e por sua mãe, Helena, por volta do ano 327 d.C. Após ser danificada no século VI, o imperador Justiniano a reconstruiu em maior escala, e grande parte da igreja atual data dessa reconstrução. Mosaicos e colunas pintadas da era das Cruzadas ainda sobrevivem em seu interior.', 'A igreja é compartilhada pelas comunidades ortodoxa grega, católica romana (franciscana) e apostólica armênia sob o histórico acordo do Status Quo. Famílias cristãs locais de Belém oram ali ao lado de peregrinos de todo o mundo, especialmente no Natal.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'pt', 'A Igreja do Santo Sepulcro, na Cidade Velha de Jerusalém, abriga os dois lugares mais sagrados do cristianismo: o Gólgota, onde Jesus foi crucificado, e o túmulo onde, segundo a tradição, ele foi sepultado e ressuscitou.', 'O imperador Constantino construiu a primeira igreja neste local no século IV; ela foi consagrada em 335 d.C. Foi destruída em 1009 e reconstruída no século XI, e os cruzados lhe deram grande parte de sua forma atual no século XII. O Edículo sobre o túmulo foi restaurado entre 2016 e 2017.', 'O cuidado da igreja é compartilhado pelas igrejas ortodoxa grega, católica romana (franciscana) e apostólica armênia, enquanto as comunidades copta, etíope e siríaca ortodoxa também mantêm capelas próprias, conforme o Status Quo de 1852. Suas portas são abertas todas as manhãs por famílias muçulmanas que guardam as chaves há séculos.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
